audit.command:
out=$(ibmcloud iam account-settings --output json 2>/dev/null) || exit 1
v=$(printf '%s\n' "$out" | sed -n 's/.*"mfa"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' | head -n 1)
case "$v" in
  ''|NONE|NONE_NO_ROPC) exit 1 ;;
  *) echo compliant ;;
esac

sgs=$(ibmcloud is security-groups --output json 2>/dev/null) || exit 1
bad=0
for g in $(printf '%s\n' "$sgs" | awk '{ o = gsub(/\{/, "{"); c = gsub(/\}/, "}") } d == 1 && /"id"[[:space:]]*:/ { s = $0; sub(/^[^:]*:[[:space:]]*"/, "", s); sub(/".*/, "", s); print s } { d += o - c }'); do
  rules=$(ibmcloud is security-group-rules "$g" --output json 2>/dev/null) || exit 1
  n=$(printf '%s\n' "$rules" | awk '
function v(s) { sub(/^[^:]*:[[:space:]]*/, "", s); gsub(/[",[:space:]]/, "", s); return s }
{ o = gsub(/\{/, "{"); c = gsub(/\}/, "}") }
d == 0 && o > 0 { dir = ""; pr = ""; pmin = ""; pmax = ""; cidr = ""; inr = 0 }
d == 1 && /"remote"[[:space:]]*:/ { inr = 1 }
d == 1 && /"direction"[[:space:]]*:/ { dir = v($0) }
d == 1 && /"protocol"[[:space:]]*:/ { pr = v($0) }
d == 1 && /"port_min"[[:space:]]*:/ { pmin = v($0) }
d == 1 && /"port_max"[[:space:]]*:/ { pmax = v($0) }
inr && /"cidr_block"[[:space:]]*:/ { cidr = v($0) }
{ d += o - c }
d == 1 && c > 0 { inr = 0 }
d == 0 && c > 0 { if (dir == "inbound" && (cidr == "0.0.0.0/0" || cidr == "::/0") && (pr == "all" || pr == "tcp") && (pmin == "" || (pmin + 0 <= 22 && pmax + 0 >= 22) || (pmin + 0 <= 3389 && pmax + 0 >= 3389))) n++ }
END { print n + 0 }')
  [ "$n" -eq 0 ] || { echo "open admin port: $g"; bad=1; }
done
[ "$bad" -eq 0 ] && echo compliant
